{
  "case_id": "xsu_sg_002_permanence_requirement",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret siger direkte, at der ikke er krav om, at tilstanden skal have været varig eller kendt som kronisk fra begyndelsen. Det modsiger vejledningen, hvor udgangspunktet er, at man ikke er berettiget, hvis tilstanden ikke fra debut kan betragtes som varig eller kronisk. Svaret nævner heller ikke étårsudgangspunktet. Ekspertrubrikken lister desuden som væsentlig fejl, at det ikke fremgår, at étårsudgangspunktet vedrører tiden før ansøgningen. Svaret forklarer, at tilstanden skal være 'langvarig' eller bestå 'på ubestemt tid', men ikke at den som udgangspunkt hverken af sig selv eller ved behandling bliver væsentligt bedre inden for en længere årrække. Det udelader også muligheden for tidsbegrænset tillæg, når varighed er sandsynliggjort."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Af de fire kritiske elementer er kun det første delvist dækket (varighed som grundlæggende betingelse). Udgangspunktet om, at tilstanden hverken af sig selv eller ved behandling bliver væsentligt bedre inden for en længere årrække, er kun omtrentligt gengivet. Étårsudgangspunktet og symptomer eller følger i mindst et år før ansøgning mangler helt. Tidsbegrænset tillæg ved sandsynliggjort varighed mangler også."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Spørgsmålet har to dele: hvornår er en funktionsnedsættelse varig, og hvad gælder, hvis den ikke er varig eller kronisk fra begyndelsen. Den anden del besvares forkert og uden det centrale om omkring et år, og svaret nævner ikke muligheden for tidsbegrænset tillæg. Svaret er på emnet, men besvarer ikke alle væsentlige dele korrekt."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til en identificerbar kilde, SU's side om handicaptillæg (su.dk/handicaptillaeg). Henvisningen er generel og kun placeret til sidst."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "SU's officielle side om handicaptillæg er en autoritativ myndighedskilde, som er relevant for emnet. Den er ikke blandt de frosne passager, men den peger på det rette område."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "De frosne passager støtter ikke påstanden om, at der ikke er krav om varighed eller kronisk karakter fra begyndelsen. De siger tværtimod det modsatte som udgangspunkt. Svaret vedlægger også kun et generelt link og ingen præcise passager. Påstanden om at 'søge igen eller sende nye oplysninger' og om 'længere tid eller på ubestemt tid' har heller ikke støtte i materialet."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at tilstanden kan være varig, hvis den er opstået for nylig og lægelige oplysninger understøtter, at den forventes at være langvarig. Det har ikke støtte, og det modsiger vejledningens udgangspunkt. Svaret tilføjer også 'forventes at bestå i længere tid eller på ubestemt tid' som definition og muligheden for at søge igen. Disse regler er ikke understøttet af materialet."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret mangler de påkrævede forbehold: udgangspunktet om, at tilstanden som udgangspunkt skal have været varig eller kronisk fra debut, og om omkring et år. Det mangler også, at tiden alene ikke afgør spørgsmålet, og at tidsbegrænset tillæg forudsætter sandsynliggjort varighed."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: varighed vurderes konkret, midlertidige tilstande opfylder som udgangspunkt ikke kravet, og dokumentation er vigtig. Konklusionerne følger af de trin, svaret selv angiver, selv om præmissen om debut er juridisk forkert."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret siger kategorisk, at 'der er ikke et krav' om varighed eller kronisk karakter fra begyndelsen. Kilden siger, at man som udgangspunkt ikke er berettiget, hvis tilstanden ikke fra debut kan betragtes som varig eller kronisk. Dermed fjernes et udgangspunkt, og modaliteten gengives forkert."
    }
  },
  "xhaile_coverage": {
    "A9": {
      "label": "yes",
      "reason": "Svaret behandler varig funktionsnedsættelse som en forudsætning og forklarer, hvornår den er varig, selv om indholdet er upræcist."
    },
    "A12": {
      "label": "no",
      "reason": "Svaret dækker ikke, at en ikke-varig funktionsnedsættelse kan vurderes varig efter omkring et år, eller at man som udgangspunkt skal have haft symptomer eller følger i mindst et år før ansøgning. Det afviser tværtimod, at tilstanden skal være varig fra debut."
    }
  },
  "overall_notes": "Svaret er læseligt og citerer en officiel SU-kilde, men det er juridisk forkert på det centrale punkt om tilstande, der ikke er varige fra debut. Det udelader étårsudgangspunktet og tidsbegrænset tillæg ved sandsynliggjort varighed, og det gør udgangspunktet om debut til en absolut afvisning af kravet."
}

